{
  "translations": [
    {
      "id": "u36044",
      "vi": "Để bắt kịp thế giới bóng đá thực tế, chúng tôi sẽ mang đến"
    },
    {
      "id": "u01033",
      "vi": "những Thử thách hoàn toàn mới trong suốt cả năm bằng cách tạo ra"
    },
    {
      "id": "u46077",
      "vi": "các kịch bản trận đấu dựa trên những trận cầu vừa diễn ra."
    },
    {
      "id": "u66532",
      "vi": "Và bây giờ là phần có lẽ thú vị nhất của EA SPORTS Football Club: "
    },
    {
      "id": "u35862",
      "vi": "‘Ủng hộ Câu lạc bộ của bạn', giải đấu ảo tương tác"
    },
    {
      "id": "u01494",
      "vi": "lớn nhất và hấp dẫn nhất thế giới."
    },
    {
      "id": "u65883",
      "vi": "Mỗi khi bạn nhận XP, bạn không chỉ đóng góp cho chính mình"
    },
    {
      "id": "u04704",
      "vi": "Vì vậy, nếu bạn là cổ động viên của Arsenal, bạn sẽ đóng góp tất cả XP của mình cho"
    },
    {
      "id": "u08695",
      "vi": "Và tất cả những cổ động viên Arsenal khác trên thế giới cũng vậy."
    },
    {
      "id": "u40124",
      "vi": "Các đội bóng được xếp hạng dựa trên đóng góp XP của cổ động viên"
    },
    {
      "id": "u68074",
      "vi": "và được trao điểm vào cuối mỗi ngày"
    },
    {
      "id": "u33402",
      "vi": "dựa trên vị trí của họ trên bảng xếp hạng."
    },
    {
      "id": "u09805",
      "vi": "Vào cuối mỗi mùa giải kéo dài một tuần,"
    },
    {
      "id": "u40470",
      "vi": "chúng tôi sẽ cộng tổng số điểm mỗi câu lạc bộ đã đạt được và các đội sẽ được thăng hạng"
    },
    {
      "id": "u67930",
      "vi": "và xuống hạng dựa trên kết quả đó."
    },
    {
      "id": "u31501",
      "vi": "Hãy làm mọi cách để mang vinh quang về cho câu lạc bộ của bạn và tránh việc xuống hạng."
    },
    {
      "id": "u07026",
      "vi": "Hơn nữa, điều này còn phụ thuộc vào chất lượng của các cổ động viên."
    },
    {
      "id": "u11461",
      "vi": "Chúng tôi xếp hạng các đội dựa trên đóng góp XP \"TRUNG BÌNH\" của cộng đồng người hâm mộ,"
    },
