    {
      "id": "u23479",
      "vi": "Xóa các mục hết hạn"
    },
    {
      "id": "u16357",
      "vi": "Xóa khỏi đội hình"
    },
    {
      "id": "u31915",
      "vi": "Các mục đã gửi sẽ bị xóa khỏi Câu lạc bộ của bạn."
    },
