    },
    {
      "id": "u66611",
      "vi": "Cầu thủ này cực kỳ nhạy bén trong việc đọc tình huống phòng ngự. Cô ấy đọc đường chuyền rất tốt và phản ứng nhanh để cắt bóng."
    },
    {
      "id": "u46164",
      "vi": "Acrobat sử dụng khả năng thể thao để tranh chấp những pha bóng mà các cầu thủ khác không thể với tới. Cầu thủ này thường xuyên có các pha phá bóng và móc bóng nghệ thuật."
    },
    {
      "id": "u01169",
      "vi": "Những cầu thủ có thế mạnh về Sức mạnh là một đối thủ đáng gờm. Họ rất khó bị đẩy ngã và tận dụng lợi thế về thể hình cùng sức mạnh khi phòng ngự."
    },
    {
      "id": "u36157",
      "vi": "Những tay săn bàn sắc bén có kỹ thuật cần thiết để trở thành nỗi ác mộng từ bất cứ vị trí nào trong phạm vi 25 yard. Họ có nhãn quan nhạy bén trước khung thành và sẽ trừng phạt mọi sai lầm của bạn."
    },
    {
      "id": "u65800",
      "vi": "Cầu thủ này đa tài và xuất sắc ở nhiều khía cạnh phòng ngự chủ chốt, tạo nên một hậu vệ toàn diện."
    },
    {
      "id": "u46851",
      "vi": "Cầu thủ này đa tài và xuất sắc ở nhiều khía cạnh nơi hàng tiền vệ, tạo nên một tiền vệ toàn diện."
    },
    {
      "id": "u01359",
      "vi": "Cầu thủ này đa tài và xuất sắc ở nhiều khía cạnh tấn công chủ chốt, tạo nên một tiền đạo toàn diện."
    },
    {
      "id": "u27807",
      "vi": "Dù trong phòng ngự hay tấn công, Aerial Threats đều thống trị trên không. Họ có khả năng bật nhảy tốt, đánh đầu chuẩn và thường sở hữu chiều cao vượt trội."
    },
    {
      "id": "u11344",
      "vi": "Cầu thủ này kiểm soát bóng tuyệt vời và rất giỏi vượt qua hậu vệ. Cô ấy cũng thường có những chiêu trò riêng để đánh bại đối thủ."
    },
    {
      "id": "u55700",
      "vi": "Cầu thủ này có khả năng phân phối bóng đặc biệt cho đồng đội. Dù là bóng sệt hay bóng bổng, đây là người bạn muốn gửi bóng để kiến tạo cơ hội."
    },
    {
      "id": "u57923",
      "vi": "Cầu thủ này có thể chạy không biết mệt mỏi. Cô ấy nỗ lực hơn hầu hết các cầu thủ khác trong cả tấn công lẫn phòng ngự. Đây là động cơ giúp đội bóng vận hành."
    },
    {
      "id": "u26240",
      "vi": "Cầu thủ này không chỉ có cú sút uy lực mà còn rất chính xác từ cự ly xa. Nếu có bóng trong không gian trống, đừng ngại thử vận may."
    },
    {
      "id": "u12863",
      "vi": "Cầu thủ này rất giỏi thực hiện các pha tạt bóng từ hai biên. Họ tạt bóng chuẩn xác, có tốc độ và có thể vẽ nên những đường cong vượt qua hậu vệ vào khu vực nguy hiểm."
    },
    {
      "id": "u36649",
      "vi": "Nhà chiến thuật"
    }
  ]
}

{
  "translations": [
