{
  "translations": [
    {
      "id": "u02170",
      "vi": "Thiết lập Tự do cho phép Deep-Lying Playmaker di chuyển khắp chiều ngang sân để hỗ trợ tấn công."
    },
    {
      "id": "u02250",
      "vi": "Di chuyển"
    },
    {
      "id": "u01911",
      "vi": "Box-to-Box"
    },
    {
      "id": "u10989",
      "vi": "BOX-TO-BOX"
    },
    {
      "id": "u02234",
      "vi": "Hỗ trợ phòng ngự"
    },
    {
      "id": "u08194",
      "vi": "Khi được yêu cầu chơi theo hướng Thu hồi bóng, tiền vệ Box-to-Box sẽ tập trung vào việc giành lại bóng trong khi vẫn hỗ trợ tấn công và phòng ngự ở khu trung tuyến."
    },
    {
      "id": "u05022",
      "vi": "Sử dụng thể lực"
    },
    {
      "id": "u50041",
      "vi": "Khi được đặt ở chế độ Cân bằng, Playmaker sẽ hỗ trợ phòng ngự khi cần thiết, đồng thời điều tiết các đợt tấn công."
    },
    {
      "id": "u52900",
      "vi": "Khi được đặt ở chế độ Tấn công, Playmaker sẽ dâng cao để hỗ trợ các đợt tấn công ở phần sân đối phương."
    },
    {
      "id": "u02766",
      "vi": "Khi được đặt ở chế độ Tự do, Playmaker sẽ có sự tự do di chuyển khắp mặt sân để tìm khoảng trống tốt nhất hỗ trợ tấn công."
    },
    {
      "id": "u01161",
      "vi": "Sáng tạo"
    },
    {
      "id": "u21955",
      "vi": "HALF-WINGER"
    },
    {
      "id": "u43650",
      "vi": "Khi được đặt ở chế độ Hỗ trợ, Half-Winger sẽ tập trung vào việc hỗ trợ lối chơi thay vì chỉ đơn thuần tấn công hoặc phòng ngự."
    },
    {
      "id": "u37572",
      "vi": "Hỗ trợ lối chơi"
    },
    {
      "id": "u65140",
      "vi": "Khi được đặt ở chế độ Tự do, cầu thủ tấn công Half-Winger này sẽ thoải mái thay đổi cánh tấn công, ngay cả trong khi triển khai bóng."
    },
    {
      "id": "u06842",
      "vi": "Cánh linh hoạt"
    },
    {
      "id": "u50760",
      "vi": "Khi ở chế độ Cân bằng, Winger sẽ cung cấp cả hỗ trợ phòng ngự lẫn tấn công. Họ kết hợp giữa việc chạy chỗ ra phía sau hàng thủ và di chuyển để nhận bóng."
    },
    {
      "id": "u52059",
      "vi": "Khi được đặt ở chế độ Tấn công, Winger sẽ tập trung dâng cao và ưu tiên chạy chỗ ra phía sau hàng thủ thay vì nhận bóng trong chân."
    },
    {
      "id": "u00971",
      "vi": "Wide Playmaker"
    },
    {
      "id": "u41545",
      "vi": "Khi được đặt ở chế độ Triển khai bóng, Wide Playmaker sẽ lùi về gần để cung cấp phương án chuyền bóng, đồng thời cân bằng cách tiếp cận để hỗ trợ phòng ngự khi cần."
    },
    {
      "id": "u44121",
      "vi": "Wide Midfielder"
    },
    {
      "id": "u11675",
      "vi": "WIDE MIDFIELDER"
    },
    {
      "id": "u17187",
      "vi": "Khi được yêu cầu Phòng ngự, Wide Midfielder sẽ lùi về hàng tiền vệ phòng ngự và bảo vệ hàng thủ."
    },
    {
      "id": "u53163",
      "vi": "Khi ở chế độ Cân bằng, Wide Midfielder sẽ bám biên để hỗ trợ kiểm soát bóng và hỗ trợ phòng ngự khi cần."
    },
    {
      "id": "u06325",
      "vi": "Phương án chuyền bóng"
    },
    {
      "id": "u64680",
      "vi": "Inside Forward"
    },
    {
      "id": "u40497",
      "vi": "INSIDE FORWARD"
    },
    {
      "id": "u02906",
      "vi": "Cắt vào trong"
    },
    {
      "id": "u01436",
      "vi": "Tấn công"
    },
    {
      "id": "u21546",
      "vi": "Rủi ro thấp"
    },
    {
      "id": "u37506",
      "vi": "Với thiết lập Cân bằng, thủ môn sẽ thỉnh thoảng rời khỏi khu vực của mình để đón những đường bóng dài hoặc bóng lỏng."
    },
    {
      "id": "u09498",
      "vi": "Khi được đặt ở chế độ Tấn công, Shadow Striker sẽ tập trung thực hiện những pha chạy chỗ muộn vào vòng cấm, lấp đầy khoảng trống phía sau tiền đạo cắm."
    },
    {
      "id": "u19067",
      "vi": "TARGET FORWARD"
    },
    {
      "id": "u13710",
      "vi": "Thể chất"
    },
    {
      "id": "u40600",
      "vi": "Khi được đặt ở chế độ Bám biên, Target Forward sẽ dạt ra rìa vòng cấm để tìm kiếm khoảng trống tạo đột biến."
    },
    {
      "id": "u23657",
      "vi": "Hỗ trợ trung lộ"
    },
    {
      "id": "u28641",
      "vi": "False 9"
    },
    {
      "id": "u02744",
      "vi": "FALSE 9"
    },
    {
      "id": "u08562",
      "vi": "Khi được đặt ở chế độ Tấn công, False 9 sẽ lùi xuống từ hàng thủ đối phương và thực hiện những pha chạy chỗ vào vòng cấm từ tuyến dưới."
    },
    {
      "id": "u15532",
      "vi": "Poacher"
    },
    {
      "id": "u51301",
      "vi": "POACHER"
    },
    {
      "id": "u20324",
      "vi": "Với thiết lập Đa năng, Poacher sẽ sử dụng khả năng phán đoán để quyết định xem liệu mình nên lùi về hỗ trợ đội bóng hay gây sức ép."
    },
    {
      "id": "u20237",
      "vi": "Khi được đặt ở chế độ Hỗ trợ, Poacher sẽ bám sát hàng thủ đối phương, tích cực gây sức ép khi họ có bóng với hy vọng buộc đối thủ mắc sai lầm."
    }
  ]
}

