    {
      "id": "u00156",
      "vi": "Để lộ khoảng trống"
    },
    {
      "id": "u09045",
      "vi": "THỦ MÔN QUÉT"
    },
    {
      "id": "u03617",
      "vi": "Phòng ngự"
    },
    {
      "id": "u28313",
      "vi": "Ưu tiên Xây dựng lối chơi khuyến khích Thủ môn quét dâng cao hơn trên sân để đón bóng và hỗ trợ lối chơi."
    },
    {
      "id": "u38351",
      "vi": "Rủi ro vừa phải"
    },
    {
      "id": "u03901",
      "vi": "Giữ vị trí"
    },
    {
      "id": "u55188",
      "vi": "HẬU VỆ CÁNH"
    },
    {
      "id": "u00779",
      "vi": "Hỗ trợ tấn công"
    },
    {
      "id": "u38413",
      "vi": "Khi ở chế độ Cân bằng, Hậu vệ cánh được tự do hơn để dâng cao và dạt biên một chút nhằm hỗ trợ tấn công."
    },
    {
      "id": "u37375",
      "vi": "HẬU VỆ BIÊN TẤN CÔNG"
    },
    {
      "id": "u24529",
      "vi": "Khi được yêu cầu hỗ trợ, Hậu vệ biên tấn công chỉ có thể dâng cao khi đội nhà kiểm soát bóng, và chỉ phòng ngự khi đội không có bóng."
    },
    {
      "id": "u00836",
      "vi": "Hỗ trợ biên"
    },
    {
      "id": "u63101",
      "vi": "HẬU VỆ ẢO"
    },
    {
      "id": "u35694",
      "vi": "Khi ở chế độ Cân bằng, Hậu vệ ảo sẽ di chuyển vào vị trí tiền vệ trung tâm khi đội nhà kiểm soát bóng."
    },
    {
      "id": "u25196",
      "vi": "Khi được yêu cầu hỗ trợ, Hậu vệ biên tấn công hiếm khi chạy nước rút về phòng ngự, trừ khi đội nhà bị phản công."
    },
    {
      "id": "u16948",
      "vi": "Hạn chế linh hoạt"
    },
    {
      "id": "u36943",
      "vi": "Với ưu tiên Cân bằng, Hậu vệ sẽ dâng lên để áp sát tiền đạo đối phương khi cần."
    },
    {
      "id": "u01511",
      "vi": "Sự quyết liệt"
    },
    {
      "id": "u08957",
      "vi": "Khi được yêu cầu chơi quyết liệt, Trung vệ dập sẽ dâng lên khu vực giữa sân để cắt đường chuyền và áp sát tiền đạo đối phương."
    },
    {
      "id": "u06217",
      "vi": "Hỗ trợ xây dựng lối chơi"
    },
    {
      "id": "u03191",
      "vi": "Cơ bản"
    }
  ]
}

{
  "translations": [
    {
      "id": "u38335",
      "vi": "Cầu thủ chỉ định: ⟦1⟧ trong ⟦2⟧"
    },
    {
      "id": "u05861",
      "vi": "Cầu thủ cùng quốc tịch/khu vực: ⟦1⟧ ⟦2⟧ trong ⟦3⟧"
    },
    {
      "id": "u32179",
      "vi": "Cầu thủ cùng giải đấu: ⟦1⟧ ⟦2⟧ trong ⟦3⟧"
    },
    {
      "id": "u02462",
      "vi": "LWB"
    },
    {
      "id": "u46784",
      "vi": "HUYỀN THOẠI"
    },
    {
      "id": "u42376",
      "vi": "Hướng và lực của những đường chọc khe bổng sẽ được hỗ trợ để đưa bóng vào đà di chuyển của cầu thủ nhận, đồng thời tránh các cầu thủ đối phương."
    },
    {
      "id": "u43677",
      "vi": "Sút xa giúp tăng cơ hội đánh bại thủ môn với các cú sút ngoài vòng cấm."
    },
    {
      "id": "u26987",
      "vi": "Chọn chỉ số này để tăng khả năng chuyền dài của bạn."
    },
    {
      "id": "u12058",
      "vi": "Sút xa quyết định độ chính xác của các cú sút khi bạn ở ngoài vòng cấm."
    },
    {
      "id": "u49935",
      "vi": "Bị đối phương vượt qua"
    },
    {
      "id": "u21911",
      "vi": "Bàn thắng thứ 10 trong mùa giải! Đạt cột mốc hai con số là một thành tích ấn tượng."
    },
    {
      "id": "u22721",
      "vi": "Khả năng tấn công tuyệt vời! Không nhiều cầu thủ ghi được 15 bàn trong một mùa giải."
    },
    {
      "id": "u26272",
      "vi": "Đạt cột mốc 20 bàn thắng trong một mùa giải là thành tích rất ấn tượng! Em nên tự hào về bản thân."
    },
    {
      "id": "u27962",
      "vi": "Đã đạt 25 bàn thắng trong mùa giải này! Thật đáng kinh ngạc."
    },
    {
      "id": "u65540",
      "vi": "Chúc mừng em! Chỉ những cầu thủ đẳng cấp thế giới mới ghi được 30 bàn trong một mùa giải."
    },
    {
      "id": "u36271",
      "vi": "Kinh ngạc thật! Đã 40 bàn thắng trong mùa giải này. Một nỗ lực phi thường!"
    },
    {
      "id": "u35479",
      "vi": "Không nhiều cầu thủ trong lịch sử ghi được 45 bàn trong một mùa giải. Thật đáng kinh ngạc!"
    },
    {
      "id": "u59976",
      "vi": "Mùa giải này em thường xuyên rời bỏ vị trí, khiến toàn đội mất đi cấu trúc phòng ngự. Điều này cần phải cải thiện ngay lập tức."
    },
    {
      "id": "u01190",
      "vi": "Mùa này trông em như lạc lối trên sân, như thể chẳng biết mình phải chơi ở đâu vậy. Cần phải chấn chỉnh ngay!"
    },
    {
      "id": "u12965",
      "vi": "Tôi không đếm nổi bao nhiêu lần em chơi sai vị trí trong mùa này. Nếu không thể chơi đúng vai trò được giao, em sẽ phải ngồi dự bị đấy!⟦1⟧⟦2⟧"
    },
    {
      "id": "u33890",
      "vi": "Cách chọn vị trí của em trong mùa giải này quá lộn xộn. Em cần phải kỷ luật hơn và bám sát vai trò được giao!"
    },
    {
      "id": "u01474",
      "vi": "VƯỢT QUA ĐỐI PHƯƠNG"
    },
    {
      "id": "u09211",
      "vi": "Đạt 30 kiến tạo trong một mùa giải là minh chứng cho tài năng đáng kinh ngạc của em."
    },
    {
      "id": "u09786",
      "vi": "Đó là 35 bàn thắng em đã tạo điều kiện ghi bàn tính đến thời điểm này của mùa giải. Xuất sắc!"
    },
    {
      "id": "u20651",
      "vi": "Đạt 50 kiến tạo trong một mùa giải chứng tỏ em là cầu thủ đẳng cấp thế giới. Một thành tích phi thường!"
    },
    {
      "id": "u01902",
      "vi": "Màn thể hiện đỉnh cao khi có được kiến tạo thứ 5 trong mùa giải."
    },
    {
      "id": "u07080",
      "vi": "Em đã có một pha kiến tạo từ đường chọc khe tuyệt vời."
    },
    {
      "id": "u31039",
      "vi": "Độ chính xác của đường chọc khe đó thật đẳng cấp. Một pha kiến tạo xứng đáng."
    },
    {
      "id": "u10679",
      "vi": "Ở cấp độ này, em không thể để mất bóng thường xuyên như vậy. Quá nhiều đường chuyền của em đã đến chân đối phương."
    },
    {
      "id": "u19270",
      "vi": "Tôi chưa bao giờ thấy cầu thủ nào làm mất bóng thường xuyên trong một mùa giải với những đường chuyền cẩu thả như vậy. Thật đáng xấu hổ!"
    },
    {
      "id": "u28237",
      "vi": "Số lượng đường chuyền hỏng của em trong mùa này khiến tôi tự hỏi liệu em có thực sự phù hợp với cấp độ này không."
    },
    {
      "id": "u15662",
      "vi": "Em cần dành nhiều thời gian hơn để rèn luyện khả năng chuyền bóng. Độ chính xác dường như là vấn đề của em trong mùa giải này."
    },
    {
      "id": "u50565",
      "vi": "Nỗ lực phòng ngự tuyệt vời khi chặn các cú sút của đối phương."
    },
    {
      "id": "u16799",
      "vi": "Em đã cho thấy khả năng chọn vị trí phòng ngự tốt để thực hiện những pha chặn bóng tuyệt vời."
    },
    {
      "id": "u58624",
      "vi": "Mùa giải này em đang chứng tỏ mình là một cầu thủ chặn bóng hiệu quả. Làm tốt lắm."
    },
    {
      "id": "u09547",
      "vi": "Tôi thực sự ấn tượng với số lần em chặn các cú sút của đối phương trong mùa giải này."
    },
    {
      "id": "u48710",
      "vi": "Khả năng chặn sút của em trong mùa này đạt đẳng cấp thế giới."
    },
    {
      "id": "u14875",
      "vi": "Phòng ngự xuất sắc khi phá bóng và loại bỏ rủi ro."
    }
  ]
}

{
  "translations": [
    {
      "id": "u40635",
      "vi": "Hãy tránh chịu phạt góc nếu có cơ hội phá bóng ra biên."
    },
    {
      "id": "u68059",
      "vi": "Việc chịu phạt góc đang tạo thêm cơ hội ghi bàn cho đối thủ."
    },
    {
      "id": "u09999",
      "vi": "Phạt góc từ đối thủ tạo áp lực lên khung thành của chúng ta và em đã để họ hưởng quá nhiều quả."
    },
    {
      "id": "u24109",
      "vi": "Pha tranh chấp dẫn đến phạt đền của em rất vụng về. Hãy cố gắng dồn cầu thủ tấn công ra xa khung thành thay vì xoạc bóng thiếu suy nghĩ."
    },
    {
      "id": "u20173",
      "vi": "Pha tranh chấp của em trong vòng cấm là một quả penalty rõ ràng. Lần sau đừng lao vào thiếu cẩn trọng như vậy."
    },
    {
      "id": "u62924",
      "vi": "Bất kỳ cầu thủ nào chịu 15 quả penalty trong một mùa giải đều cần xem lại bản thân mình!"
    },
    {
      "id": "u58183",
      "vi": "Tôi chưa bao giờ thấy cầu thủ nào chịu 20 quả penalty trong một mùa giải. Em nên cảm thấy xấu hổ về bản thân mình!"
    },
    {
      "id": "u18612",
      "vi": "Ai cũng có thể mắc lỗi dẫn đến penalty, nhưng để chịu tới hai quả trong một mùa giải thì đúng là thiếu cẩn trọng."
    },
    {
      "id": "u19979",
      "vi": "Đó là quả penalty thứ tư em phải chịu trong mùa giải này! Tôi không hài lòng chút nào."
    },
    {
      "id": "u20797",
      "vi": "Thói quen phạm lỗi dẫn đến penalty của em đang khiến đội bóng phải trả giá trong mùa giải này. Đó đã là quả thứ sáu rồi!"
    },
    {
      "id": "u17850",
      "vi": "Tôi rất tức giận! Đó là tám quả penalty em đã gây ra trong mùa giải này."
    },
    {
      "id": "u45912",
      "vi": "Nỗ lực tạt bóng tốt, hãy tiếp tục duy trì những quả tạt vào vòng cấm."
    },
    {
      "id": "u36782",
      "vi": "Em đang lãng phí các cơ hội vì dồn quá nhiều lực vào những quả tạt."
    },
    {
      "id": "u00575",
      "vi": "Cố gắng đừng tạt quá mạnh, hãy giảm bớt lực đi."
    },
    {
      "id": "u15622",
      "vi": "Các quả tạt của em chưa tốt. Quá nhiều cơ hội đã bị bỏ lỡ!"
    },
    {
      "id": "u28712",
      "vi": "Các quả tạt của em cần cải thiện. Em đang lãng phí quá nhiều cơ hội."
    },
    {
      "id": "u16689",
      "vi": "Hãy cải thiện vị trí phòng ngự để hạn chế phạm những lỗi không cần thiết."
    },
    {
      "id": "u22593",
      "vi": "Hãy cẩn trọng khi tranh chấp với đối phương để tránh những chiếc thẻ không đáng có."
    },
    {
      "id": "u50492",
      "vi": "Em thực hiện quá nhiều pha xoạc bóng thiếu cẩn trọng. Em cần cải thiện khả năng chọn thời điểm."
    },
    {
      "id": "u25032",
      "vi": "Hãy chú ý đừng phạm lỗi ở 1/3 sân nhà để tránh tạo ra các quả đá phạt nguy hiểm."
    },
    {
      "id": "u60790",
      "vi": "Việc phạm lỗi quá nhiều ở các khu vực nguy hiểm đang gây áp lực không đáng có lên đội bóng."
    },
    {
      "id": "u56102",
      "vi": "Em cần cải thiện kỹ năng xoạc bóng. Em đang phạm lỗi quá nhiều rồi."
    },
    {
      "id": "u57712",
      "vi": "Em cần dành nhiều thời gian hơn để tập luyện xoạc bóng. Em đang phạm lỗi quá nhiều trong mùa giải này."
    },
    {
      "id": "u60568",
      "vi": "Xoạc bóng rõ ràng không phải là thế mạnh của em. Em cần học cách cướp bóng từ đối phương mà không phạm lỗi."
    },
    {
      "id": "u60962",
      "vi": "Em đang phạm lỗi quá nhiều trong mùa giải này với những pha xoạc bóng kém cỏi. Như vậy là chưa đủ tốt!"
    },
    {
      "id": "u68697",
      "vi": "Các đồng đội sẽ không cảm ơn em vì đã phạm lỗi quá nhiều trong mùa giải này đâu, và tôi cũng vậy."
    },
    {
      "id": "u25253",
      "vi": "Kỹ năng xoạc bóng kém của em đã dẫn đến quá nhiều lỗi cho chúng ta. Tôi bắt đầu thấy mệt mỏi với sự thiếu kỷ luật của em trong mùa giải này rồi đấy."
    },
    {
      "id": "u29573",
      "vi": "Khả năng xoạc bóng của em mùa này thật tồi tệ. Tôi không thể đếm xuể số lỗi mà em đã gây ra nữa."
    },
    {
      "id": "u20070",
      "vi": "Làm tốt lắm, kiếm về được quả phạt."
    },
    {
      "id": "u24041",
      "vi": "Làm tốt lắm khi mang về những quả đá phạt đó. Đối phương không thể theo kèm được em."
    },
    {
      "id": "u28599",
      "vi": "Lối chơi xuất sắc, làm tốt lắm khi buộc đối phương phải phạm lỗi với em."
    },
    {
      "id": "u15480",
      "vi": "Em đã thể hiện những kỹ thuật rất hay trên sân. Đối phương không còn cách nào khác ngoài việc phải phạm lỗi với em."
    },
    {
      "id": "u24800",
      "vi": "Em đã thể hiện kỹ thuật tuyệt vời để ghi bàn từ quả đá phạt đó."
    },
    {
      "id": "u19652",
      "vi": "Bàn thắng ấn tượng từ quả đá phạt. Kỹ năng của em thực sự đỉnh cao."
    },
    {
      "id": "u30452",
      "vi": "Quả đá phạt kém quá. Em cần luyện tập nhiều hơn."
    },
    {
      "id": "u13626",
      "vi": "Đá phạt không phải thế mạnh của em. Em cần luyện tập nhiều hơn trong các buổi tập."
    },
    {
      "id": "u19602",
      "vi": "Huấn luyện viên sẽ nhận xét về màn trình diễn của em trong suốt trận đấu."
    }
  ]
}

{
  "translations": [
    {
      "id": "u07659",
      "vi": "Thêm một màn trình diễn chuyền bóng xuất sắc nữa! Em luôn tìm thấy đồng đội của mình."
    },
    {
      "id": "u29351",
      "vi": "Em đang khẳng định mình là một trong những chân chuyền hay nhất giải đấu mùa này."
    },
    {
      "id": "u27044",
      "vi": "Làm tốt lắm! Mọi nỗ lực chăm chỉ đã giúp em lập một cú hat-trick."
    },
    {
      "id": "u11807",
      "vi": "Một cú hat-trick thật ấn tượng!"
    },
    {
      "id": "u67144",
      "vi": "Tầm nhìn tuyệt vời khi đánh đầu kiến tạo cho đồng đội."
    },
    {
      "id": "u45755",
      "vi": "Những pha đánh đầu cho đồng đội của em rất hiệu quả."
    },
    {
      "id": "u00621",
      "vi": "Những pha đánh đầu chuyền bóng của em hôm nay rất đẳng cấp."
    },
    {
      "id": "u36824",
      "vi": "Em luôn đánh đầu tìm đến đúng vị trí đồng đội. Làm tốt lắm."
    },
    {
      "id": "u15508",
      "vi": "Pha cắt bóng tuyệt vời nhờ khả năng đọc tình huống."
    },
    {
      "id": "u28621",
      "vi": "Khả năng đọc tình huống và cắt bóng quá xuất sắc."
    },
    {
      "id": "u04857",
      "vi": "Tầm nhìn tuyệt vời trong những đường chuyền đó, làm tốt lắm trong việc tạo cơ hội cho đồng đội."
    },
    {
      "id": "u37504",
      "vi": "Làm tốt lắm khi tạo ra những pha bóng đó bằng các đường chuyền quan trọng của mình."
    },
    {
      "id": "u45340",
      "vi": "Độ chính xác trong những đường chuyền kiến tạo cho đồng đội của em là hạng nhất."
    },
    {
      "id": "u38143",
      "vi": "Số đường chuyền quan trọng mà em thực hiện được mùa này thật huyền thoại."
    },
    {
      "id": "u07139",
      "vi": "Thực hiện các đường chuyền quan trọng cho đồng đội đã trở thành thế mạnh lớn của em mùa này. Hãy tiếp tục phát huy."
    },
    {
      "id": "u16089",
      "vi": "Em có nhãn quan rất tốt cho một đường chuyền quan trọng. Tầm nhìn của em mùa này thật sự xuất sắc."
    },
    {
      "id": "u11667",
      "vi": "Rất ít cầu thủ thực hiện được nhiều đường chuyền quan trọng như vậy trong một mùa giải. Thầy thực sự rất ấn tượng."
    },
    {
      "id": "u46138",
      "vi": "Có vẻ như mùa này em không ngừng tìm thấy đồng đội bằng những đường chuyền quan trọng. Em đã chơi rất xuất sắc."
    },
    {
      "id": "u37855",
      "vi": "Thầy không nhớ đã từng thấy cầu thủ nào thực hiện nhiều đường chuyền quan trọng trong một mùa giải như vậy. Em đã thi đấu đẳng cấp thế giới."
    },
    {
      "id": "u50299",
      "vi": "Đừng lo lắng, hãy ngẩng cao đầu lên. Bỏ lỡ khung thành trống là chuyện thường, đừng để nó ảnh hưởng đến em."
    },
    {
      "id": "u17058",
      "vi": "Hãy bình tĩnh hơn để đưa bóng vào khung thành trống."
    },
    {
      "id": "u36522",
      "vi": "Ở đẳng cấp này, em không được phép bỏ lỡ mục tiêu như vậy. Chuyện này đã xảy ra quá thường xuyên mùa giải này rồi."
    },
    {
      "id": "u25939",
      "vi": "Thầy chưa từng thấy cầu thủ nào bỏ lỡ khung thành trống nhiều lần như vậy trong một mùa giải. Em cần phải cải thiện khả năng dứt điểm."
    },
    {
      "id": "u02042",
      "vi": "Lối chơi vị trí của em vô kỷ luật đến mức đáng lo ngại. Em hiếm khi có mặt ở nơi mà mình cần phải đứng!"
    },
    {
      "id": "u35197",
      "vi": "Vị trí của em trên sân rất lộn xộn. Em cần chơi kỷ luật hơn và bám sát vai trò được giao!"
    },
    {
      "id": "u51905",
      "vi": "Khả năng chọn vị trí thật tệ hại. Em đang làm cả đội thất vọng đấy."
    },
    {
      "id": "u13911",
      "vi": "Em trông như bị lạc lối trên sân vậy, cứ như thể không biết mình phải chơi ở đâu. Chuyện này cần phải được chấn chỉnh ngay!"
    },
    {
      "id": "u15888",
      "vi": "Khả năng chọn vị trí của em hôm nay khá ổn, nhưng vẫn còn chỗ để cải thiện."
    },
    {
      "id": "u13681",
      "vi": "Ở đẳng cấp này, em không được phép thường xuyên mất vị trí như vậy."
    },
    {
      "id": "u29896",
      "vi": "Em có xu hướng rời bỏ vị trí, điều đó khiến cả đội mất đi sự kết nối. Chuyện này cần phải cải thiện!"
    },
    {
      "id": "u68224",
      "vi": "Phản lưới nhà là điều có thể xảy ra. Sự tập trung là chìa khóa."
    },
    {
      "id": "u34311",
      "vi": "Phản lưới nhà có thể xảy ra với bất kỳ ai, nhưng việc ý thức hơn về vị trí phòng ngự sẽ giúp giảm thiểu rủi ro."
    },
    {
      "id": "u08918",
      "vi": "Thật không may với bàn phản lưới đó. Chuyện đó vẫn xảy ra mà. Hãy rút kinh nghiệm và đừng để nó làm lung lay sự tự tin của em."
    },
    {
      "id": "u27634",
      "vi": "10 bàn phản lưới mùa này rồi. Cố nhớ xem em đang đá cho đội nào đi chứ!"
    },
    {
      "id": "u25941",
      "vi": "Em đang đá phản lưới nhà quá thường xuyên mùa giải này. Đây đã là lần thứ 15 rồi. Hãy đảm bảo đó là lần cuối cùng nhé!"
    },
    {
      "id": "u22452",
      "vi": "Em ghi quá nhiều bàn phản lưới mùa này đến mức thầy bắt đầu nghĩ em đang chơi cho đối thủ đấy. Em đã khiến đội nhà mất tới 20 bàn rồi!"
    },
    {
      "id": "u22005",
      "vi": "Ai cũng có thể phản lưới nhà mà. Hãy quên nó đi."
    }
  ]
}

{
  "translations": [
    {
      "id": "u23367",
      "vi": "Vài bàn phản lưới trong một mùa giải không có gì đáng lo ngại đâu. Chuyện đó ai cũng có thể gặp phải mà."
    },
    {
      "id": "u40611",
      "vi": "Kỹ thuật và tầm nhìn tốt khi tìm kiếm đồng đội."
    },
    {
      "id": "u68052",
      "vi": "Pha đánh gót táo bạo, cách rất hay để đưa bóng đến cho đồng đội."
    },
    {
      "id": "u33567",
      "vi": "Pha đánh gót tinh quái đã cho thấy sự tự tin của em."
    },
    {
      "id": "u10013",
      "vi": "Em đã đánh lừa cầu thủ theo kèm bằng pha đánh gót đó."
    },
    {
      "id": "u11643",
      "vi": "Chuyền bóng kém quá, đừng hoảng và hãy bình tĩnh."
    },
    {
      "id": "u27488",
      "vi": "Độ chính xác trong các đường chuyền của em rất kém. Em cần lựa chọn tốt hơn khi tìm đồng đội."
    },
    {
      "id": "u52189",
      "vi": "Chuyền bóng tệ lắm, hãy cố gắng quan sát đồng đội trước khi chuyền."
    },
    {
      "id": "u41815",
      "vi": "Kỹ năng và kỹ thuật chuyền bóng rất tốt."
    },
    {
      "id": "u05607",
      "vi": "Em đã phô diễn sự khéo léo với những đường chuyền sắc bén đó."
    },
    {
      "id": "u26285",
      "vi": "Chuyền một chạm đẳng cấp."
    },
    {
      "id": "u12918",
      "vi": "Em đã cho thấy khả năng nhận thức và kỹ thuật tốt để tìm đồng đội bằng những đường chuyền một chạm."
    },
    {
      "id": "u02724",
      "vi": "Thời điểm chuyền của em bị lệch, phải nhả bóng sớm hơn để tránh làm đồng đội rơi vào thế việt vị."
    },
    {
      "id": "u39072",
      "vi": "Cần đọc tình huống nhanh hơn để tránh lỗi việt vị."
    },
    {
      "id": "u64856",
      "vi": "Hãy chú ý hơn đến vị trí của đồng đội để tránh những đường chuyền dẫn đến việt vị."
    },
    {
      "id": "u45411",
      "vi": "Tầm nhìn tuyệt vời khi tìm thấy đồng đội ở khoảng trống."
    },
    {
      "id": "u37561",
      "vi": "Tầm nhìn ấn tượng với những đường chuyền chọc khe cho đồng đội."
    },
    {
      "id": "u04916",
      "vi": "Em đã thể hiện đẳng cấp với những đường chọc khe ấn tượng."
    },
    {
      "id": "u52549",
      "vi": "Lần sau hãy cố gắng tập trung và giữ bình tĩnh khi thực hiện đá phạt đền."
    },
    {
      "id": "u14076",
      "vi": "Em đã đá hỏng phạt đền. Chuyện đó vẫn xảy ra mà. Hãy quên nó đi và tập trung ghi bàn trong lần tới."
    },
    {
      "id": "u29668",
      "vi": "Ngay cả những tiền đạo vĩ đại nhất cũng có lúc đá hỏng phạt đền. Đừng để chuyện này ảnh hưởng đến sự tự tin của em."
    },
    {
      "id": "u05265",
      "vi": "Tôi không nhớ nổi em đã đá hỏng bao nhiêu quả phạt đền mùa này rồi. Độ chính xác trong cú sút của em cần phải cải thiện đáng kể."
    },
    {
      "id": "u21013",
      "vi": "Thực hiện phạt đền xuất sắc."
    },
    {
      "id": "u18196",
      "vi": "Giữ bình tĩnh rất tốt khi ghi bàn trên chấm phạt đền."
    },
    {
      "id": "u51196",
      "vi": "Pha đá phạt đền dứt khoát."
    },
    {
      "id": "u51212",
      "vi": "Hãy cố gắng khiến đối phương phạm lỗi và giành quả đá phạt, thay vì để mất bóng."
    },
    {
      "id": "u61835",
      "vi": "Hãy cố gắng chuyền bóng thay vì để mất quyền kiểm soát vào tay đối thủ."
    },
    {
      "id": "u21040",
      "vi": "Thay vì biếu không bóng cho đối thủ ở một phần ba cuối sân, hãy cố gắng giữ nhịp hoặc kiếm một quả phạt."
    },
    {
      "id": "u18208",
      "vi": "Đá tiền đạo không chỉ là ghi bàn. Mà còn là giữ bóng ở một phần ba cuối sân, điều này cần phải cải thiện."
    },
    {
      "id": "u30233",
      "vi": "Việc để mất bóng ở những khu vực nguy hiểm khiến hàng phòng ngự chịu áp lực không đáng có."
    },
    {
      "id": "u13369",
      "vi": "Sự cẩu thả khi kiểm soát bóng quanh khu vực sân nhà của em đã đặt khung thành chúng ta vào thế nguy hiểm."
    },
    {
      "id": "u22449",
      "vi": "Giữ bóng ở khu vực giữa sân là điều thiết yếu để kiểm soát thế trận."
    },
    {
      "id": "u17163",
      "vi": "Tránh để mất bóng, đừng để đối phương kiểm soát trận đấu."
    },
    {
      "id": "u61212",
      "vi": "Hãy chú ý đến vị trí của mình và hậu vệ cuối cùng để tránh lỗi việt vị."
    },
    {
      "id": "u48051",
      "vi": "Hãy cố gắng cải thiện thời điểm chạy chỗ. Luôn để mắt đến hậu vệ cuối cùng."
    },
    {
      "id": "u18680",
      "vi": "Em cần căn thời gian chạy chỗ vượt qua hậu vệ cuối cùng tốt hơn để không bị bắt việt vị."
    },
    {
      "id": "u14158",
      "vi": "Một cầu thủ đẳng cấp không nên bị bắt việt vị nhiều lần như vậy trong một mùa giải."
    },
    {
      "id": "u14932",
      "vi": "Tôi đang dần mất kiên nhẫn rồi đấy. Mùa này em bị bắt việt vị quá nhiều lần rồi!"
    },
    {
      "id": "u18744",
      "vi": "Em không thể ghi bàn nếu cứ liên tục bị bắt việt vị. Như thế là không đạt yêu cầu!"
    }
  ]
}

