{
  "translations": [
    {
      "id": "u39042",
      "vi": "Em vừa thể hiện đẳng cấp bậc thầy trong những pha tắc bóng. Thầy không đếm xuể số lần em làm được điều đó trong mùa giải này. Một màn trình diễn phòng ngự xuất sắc!"
    },
    {
      "id": "u19629",
      "vi": "Tránh những pha biểu diễn rườm rà. Nó không phải lúc nào cũng hiệu quả. Hãy tìm cách phối hợp với đồng đội nhiều hơn."
    },
    {
      "id": "u11885",
      "vi": "Thật tuyệt khi thấy em vận dụng kỹ năng của mình trên sân. Những pha xử lý đó rất ấn tượng."
    },
    {
      "id": "u27109",
      "vi": "Những pha xử lý đó thật hoa mỹ. Rất ấn tượng trên sân."
    },
    {
      "id": "u46488",
      "vi": "Hãy quan sát đồng đội ở vị trí thuận lợi trước khi thực hiện đường chuyền đó."
    },
    {
      "id": "u00938",
      "vi": "Chuyền về cũng có tác dụng của nó miễn là tìm đúng đồng đội. Nhưng em lại chuyền hỏng quá nhiều."
    },
    {
      "id": "u36529",
      "vi": "Em đã đặt đội vào thế khó không đáng có với những đường chuyền về cẩu thả. Hãy tìm phương án chuyền bóng tốt hơn nếu chuyền về không phải là giải pháp tối ưu."
    },
    {
      "id": "u57843",
      "vi": "Hãy nhớ quan sát kỹ khi thực hiện tạt bóng. Độ chính xác của em trong mùa giải này rất tệ."
    },
    {
      "id": "u70719",
      "vi": "Tạt bóng đòi hỏi nhiều kỹ thuật hơn là chỉ phất bóng về phía đồng đội và cầu may! Thầy rất thất vọng về độ chính xác của em mùa giải này."
    },
    {
      "id": "u05778",
      "vi": "Em cần cải thiện khả năng tạt bóng. Đôi lúc em xử lý hơi lãng phí."
    },
    {
      "id": "u17345",
      "vi": "Độ chính xác trong các quả tạt của em đang khiến thầy lo ngại. Mùa giải này có quá nhiều quả tạt không đến được vị trí đồng đội."
    },
    {
      "id": "u47192",
      "vi": "Đồng đội sẽ không hài lòng với những quả tạt thiếu chính xác của em mùa giải này đâu. Em cần cải thiện."
    },
    {
      "id": "u38991",
      "vi": "Thầy lo lắng vì khả năng tạt bóng của em quá tệ mùa giải này. Đây là điều em cần phải tập luyện thêm."
    },
    {
      "id": "u05191",
      "vi": "Luôn quan sát và cố gắng tìm đồng đội trong vòng cấm khi thực hiện tạt bóng."
    },
    {
      "id": "u37235",
      "vi": "Hãy cố gắng cải thiện những quả tạt của em."
    },
    {
      "id": "u63693",
      "vi": "Những quả tạt của em rất tệ. Hãy nhắm vào đồng đội trong vòng cấm, đừng chỉ tạt bóng cầu may."
    },
    {
      "id": "u40235",
      "vi": "Hãy tìm đồng đội ở phía trên trước khi thực hiện đường chuyền đó."
    },
    {
      "id": "u08824",
      "vi": "Những đường chuyền lên phía trên của em thường xuyên hỏng. Em cần nỗ lực hơn để cải thiện sự bình tĩnh và độ chính xác khi chuyền bóng."
    },
    {
      "id": "u34241",
      "vi": "Hãy đánh giá các lựa chọn trước khi thực hiện đường chuyền lên. Em đã để mất bóng quá dễ dàng."
    },
    {
      "id": "u03082",
      "vi": "Nếu chuyền dài khó quá thì hãy chọn phương án chuyền ngắn."
    },
    {
      "id": "u60608",
      "vi": "Chuyền dài sẽ trở nên vô nghĩa nếu không chính xác. Em đã chuyền hỏng quá nhiều."
    },
    {
      "id": "u48816",
      "vi": "Hãy đảm bảo đồng đội đang ở vị trí trống trải để nhận đường chuyền ngắn."
    },
    {
      "id": "u24166",
      "vi": "Em đang gặp vấn đề với những đường chuyền ngắn. Hãy cố gắng tìm đồng đội ở vị trí trống."
    },
    {
      "id": "u20221",
      "vi": "Hãy chắc chắn đồng đội đã sẵn sàng nhận bóng trước khi chuyền, đặc biệt là ở cự ly gần."
    },
    {
      "id": "u57063",
      "vi": "Nếu không thể chuyền ngang, hãy cố gắng giữ bóng hoặc đột phá qua đối thủ."
    },
    {
      "id": "u29885",
      "vi": "Khả năng chuyền ngang của em còn nhiều hạn chế. Em để mất bóng quá thường xuyên."
    },
    {
      "id": "u14373",
      "vi": "Em để mất bóng quá nhiều lần khi chuyền ngang. Nếu không có cơ hội chuyền thì đừng ép buộc."
    },
    {
      "id": "u01328",
      "vi": "Làm tốt lắm, thắng trong những pha tranh chấp trên không."
    },
    {
      "id": "u19456",
      "vi": "Làm tốt lắm khi tranh chấp trên không với đối thủ."
    },
    {
      "id": "u24621",
      "vi": "Rất tốt khi thấy em luôn là người đón được bóng trước đối thủ. Một màn trình diễn tuyệt vời trong các pha bóng trên không!"
    },
    {
      "id": "u55736",
      "vi": "Em cần cẩn thận hơn trong những pha phòng ngự để không phải nhận thêm thẻ."
    },
    {
      "id": "u26246",
      "vi": "Hãy cẩn thận, chúng ta không thể chơi thiếu người được."
    },
    {
      "id": "u12883",
      "vi": "Chiếc thẻ vàng đó khiến em phải thi đấu rụt rè trong suốt phần còn lại của trận đấu. Hãy chú ý kỷ luật!"
    },
    {
      "id": "u54038",
      "vi": "Thẻ vàng sẽ tích lũy suốt cả mùa giải. Đừng để mình bị treo giò vì phạm lỗi không đáng có."
    },
    {
      "id": "u14180",
      "vi": "12 thẻ vàng trong một mùa giải là điều hoàn toàn không thể chấp nhận được!"
    },
    {
      "id": "u15712",
      "vi": "Hiếm khi thầy thấy cầu thủ nào tắc bóng thiếu kỷ luật như em. Chiếc thẻ vàng thứ 15 mùa này cho thấy em vẫn còn phải học hỏi nhiều."
    },
    {
      "id": "u61332",
      "vi": "Bị phạm lỗi"
    }
  ]
}

