{
  "translations": [
    {
      "id": "u51957",
      "vi": "TÌM KIẾM CẦU THỦ"
    },
    {
      "id": "u09436",
      "vi": "Tìm kiếm cầu thủ"
    },
    {
      "id": "u59135",
      "vi": "Tuyển trạch cầu thủ"
    },
    {
      "id": "u17031",
      "vi": "Có nhiều hình thức giao dịch.⟦1⟧⟦2⟧Chuyển nhượng là phương án cố định nhưng tốn kém hơn.⟦3⟧⟦4⟧Cho mượn là công cụ hữu ích cho các giải pháp ngắn hạn.⟦5⟧⟦6⟧Trong khi đó, mượn kèm điều khoản mua đứt mang lại sự linh hoạt hơn khi ngân sách của bạn bị hạn chế."
    },
    {
      "id": "u68099",
      "vi": "CHUYỂN NHƯỢNG CẦU THỦ"
    },
    {
      "id": "u67830",
      "vi": "Chuyển nhượng"
    },
    {
      "id": "u00712",
      "vi": "Khích lệ có lẽ không phải lúc nào cũng là ý hay. Phản ứng và vùng tâm lý lý tưởng của mỗi cầu thủ đều khác nhau tùy thuộc vào tính cách của họ.⟦1⟧⟦2⟧Hãy để mắt đến họ để tránh tình trạng tự mãn."
    },
    {
      "id": "u58094",
      "vi": "Mỗi cầu thủ đều có cá tính riêng và họ phản ứng khác nhau khi được khen ngợi, động viên hoặc chỉ trích, vì vậy bạn phải khám phá tính cách của các cầu thủ trong đội."
    },
    {
      "id": "u63542",
      "vi": "Tính cách cầu thủ"
    },
    {
      "id": "u05927",
      "vi": "Các tuyển trạch viên của bạn sẽ thường xuyên gợi ý những cầu thủ mà bạn có thể quan tâm."
    },
    {
      "id": "u29411",
      "vi": "Đảm bảo cầu thủ đó phù hợp với đội bóng của bạn là điều mấu chốt. Có thể truy cập các trang báo cáo tiếp theo từ đây."
    },
    {
      "id": "u25855",
      "vi": "TUYỂN TRẠCH CẦU THỦ"
    },
    {
      "id": "u28705",
      "vi": "Báo cáo tuyển trạch"
    },
    {
      "id": "u27024",
      "vi": "Tuyển trạch viên của bạn có thể tạo mạng lưới trên khắp thế giới để khám phá những cầu thủ mới.⟦1⟧⟦2⟧Hãy để trống một trong các tuyển trạch viên nếu bạn muốn nhận báo cáo về các đối thủ sắp tới."
    },
    {
      "id": "u08524",
      "vi": "Mặc dù có thể tốn kém, nhưng việc có một mạng lưới tuyển trạch tốt có thể mang lại hiệu quả trên Transfer Market.⟦1⟧Học viện trẻ của bạn cũng có mạng lưới tuyển trạch riêng, sẵn sàng để tìm ra tài năng trẻ tiếp theo."
    },
    {
      "id": "u23369",
      "vi": "Độ sắc bén và Tinh thần có thể ảnh hưởng đáng kể đến hiệu suất của cầu thủ. Tác động của chúng sẽ được hiển thị bên cạnh chỉ số cơ bản.⟦1⟧⟦2⟧Độ sắc bén sẽ ảnh hưởng đến các chỉ số thể chất và kỹ thuật.⟦3⟧⟦4⟧Trong khi Tinh thần sẽ ảnh hưởng đến các chỉ số tâm lý."
    },
    {
      "id": "u55423",
      "vi": "Độ sắc bén của cầu thủ sẽ tăng cường hiệu suất thi đấu, giúp họ phản ứng nhanh và hiệu quả hơn trong trận. Mọi cầu thủ cần được tập luyện và ra sân để duy trì độ sắc bén."
    },
    {
      "id": "u18728",
      "vi": "Thể lực là chìa khóa cho khả năng vận động của cầu thủ trong trận đấu. Hãy cho các cầu thủ đủ thời gian nghỉ ngơi và hồi phục để đảm bảo thể lực của họ đạt đỉnh cao cho những trận đấu quan trọng nhất."
    },
    {
      "id": "u67966",
      "vi": "Tinh thần của cầu thủ có ảnh hưởng đến hiệu suất thi đấu. Hãy giữ cho cầu thủ hạnh phúc bằng cách đáp ứng các yêu cầu về chuyên môn và hợp đồng của họ. Tăng tinh thần của họ khi bạn nói về họ trước báo giới."
    },
    {
      "id": "u23880",
      "vi": "Hãy để mắt đến những điểm mạnh và điểm yếu trong thiết lập đội hình của bạn, cũng như sự bao quát vị trí trên sân của các vai trò cầu thủ."
    },
    {
      "id": "u02899",
      "vi": "Tập luyện sẽ cải thiện độ sắc bén của cầu thủ nhưng đổi lại sẽ tiêu tốn năng lượng của họ. Những cầu thủ không tập luyện sẽ hồi phục năng lượng, nhưng điều đó sẽ làm giảm một phần độ sắc bén của họ."
    },
    {
      "id": "u43018",
      "vi": "Độ sắc bén có được từ tập luyện và thời gian thi đấu sẽ tăng cường khả năng của cầu thủ trong trận. Một cầu thủ thiếu độ sắc bén sẽ không thể chơi với phong độ cao nhất trong các trận đấu."
    },
    {
      "id": "u22583",
      "vi": "Nếu bạn tự chơi các bài tập luyện thay vì mô phỏng, bạn sẽ cải thiện kỹ năng của chính mình với tư cách là người chơi. Làm tốt các bài tập này cũng sẽ cải thiện mức độ hiệu quả của đội bóng khi bạn mô phỏng các buổi tập."
    },
    {
      "id": "u49938",
      "vi": "Độ sắc bén và Năng lượng là những yếu tố then chốt để đạt hiệu suất cao.⟦1⟧⟦2⟧Các Kế hoạch Tự động cung cấp một cách đơn giản để cân bằng các yếu tố này cho toàn bộ đội hình của bạn."
    },
    {
      "id": "u15818",
      "vi": "Các ngưỡng xác định mức độ tập trung của cầu thủ vào Độ sắc bén hoặc Năng lượng tại bất kỳ thời điểm nào."
    },
    {
      "id": "u64568",
      "vi": "Dự báo về cách Năng lượng và Độ sắc bén sẽ thay đổi trước trận đấu tiếp theo được cung cấp tại đây.⟦1⟧⟦2⟧Độ sắc bén của cầu thủ sẽ giảm nếu họ không được ra sân nhiều."
    },
    {
      "id": "u36194",
      "vi": "PlayStyle là những sự tăng cường mạnh mẽ mà cầu thủ có thể sở hữu, áp dụng cho các hành động hoặc khoảnh khắc cụ thể trong trận đấu. Những sự tăng cường tạm thời này chỉ có hiệu lực trong một trận đấu."
    },
    {
      "id": "u70642",
      "vi": "Một số sự kiện sẽ ảnh hưởng đến cả đội, một số chỉ ảnh hưởng đến một vài cầu thủ nhất định và một số sẽ yêu cầu quyết định từ bạn.⟦1⟧⟦2⟧Hãy luôn sẵn sàng và linh hoạt để vượt qua chúng."
    },
    {
      "id": "u67085",
      "vi": "Hãy đảm bảo đội trẻ của bạn có ít nhất 4 cầu thủ đá chính và 1 thủ môn để đủ điều kiện tham gia các giải đấu 5v5."
    },
    {
      "id": "u32995",
      "vi": "Tham gia các giải đấu 5v5 là cơ hội tốt để các cầu thủ trẻ tăng tốc quá trình phát triển của họ."
    }
  ]
}

{
  "translations": [
    {
      "id": "u48251",
      "vi": "Bạn có thể cấu hình cài đặt để cầu thủ trẻ thi đấu theo cấp độ chỉ số hiện tại hoặc theo tiềm năng tối đa của họ."
    },
    {
      "id": "u68226",
      "vi": "Bạn cũng có thể yêu cầu tuyển trạch viên đánh giá cầu thủ trẻ dựa trên năng lực vị trí, để biết các ứng viên còn cách xa yêu cầu của đội bóng bao nhiêu."
    },
    {
      "id": "u20958",
      "vi": "Nhân viên của bạn sẽ đưa ra các báo cáo làm nổi bật mức độ phù hợp của một ứng viên trẻ với hồ sơ mà bạn đang tìm kiếm."
    },
    {
      "id": "u70735",
      "vi": "Báo cáo tuyển trạch cầu thủ trẻ"
    },
    {
      "id": "u32595",
      "vi": "Học viện trẻ mang đến cho bạn cơ hội phát triển thế hệ ngôi sao tiếp theo của câu lạc bộ với chi phí thấp."
    },
    {
      "id": "u44661",
