    },
    {
      "id": "u14026",
      "vi": "Việc chọn Kế hoạch phát triển phù hợp sẽ đảm bảo họ trở thành cầu thủ thích hợp cho đội hình chính của bạn."
    },
    {
      "id": "u01043",
      "vi": "Ký hợp đồng"
    },
    {
      "id": "u21596",
      "vi": "Archetype là bộ đặc điểm nhận dạng được thiết kế riêng cho cầu thủ của bạn, lấy cảm hứng từ những huyền thoại bóng đá đã để lại dấu ấn trong môn thể thao vua."
    },
    {
      "id": "u13322",
      "vi": "Đưa cầu thủ tham gia các buổi tập luyện sẽ giúp tăng chỉ số. Tập luyện cũng sẽ cải thiện sự ưu ái của Huấn luyện viên dành cho bạn."
    },
    {
      "id": "u15601",
      "vi": "Hoàn thành Nhiệm vụ trận đấu giúp bạn thúc đẩy sự phát triển của cầu thủ và đảm bảo duy trì mối quan hệ tốt với Huấn luyện viên."
    },
    {
      "id": "u02736",
      "vi": "Tính cách cầu thủ"
    },
    {
      "id": "u18575",
      "vi": "Tính cách sẽ ảnh hưởng đến những PlayStyle mà cầu thủ của bạn có thể sở hữu."
    },
    {
      "id": "u08342",
      "vi": "Người đại diện"
    },
    {
      "id": "u57389",
      "vi": "Đàm phán"
    },
    {
      "id": "u21172",
      "vi": "Câu lạc bộ càng lớn và yêu cầu lương càng cao, thì các nhiệm vụ bạn cần hoàn thành để có được hợp đồng đó càng khó."
    },
    {
      "id": "u68868",
      "vi": "Yêu cầu hợp đồng"
    },
    {
      "id": "u26300",
      "vi": "Nhiệm vụ"
    },
    {
      "id": "u69667",
      "vi": "Đề xuất của người đại diện"
    },
