    },
    {
      "id": "u35344",
      "vi": "Đã chặn nhận đề nghị chuyển nhượng."
    },
    {
      "id": "u06979",
      "vi": "ĐÃ CHUYỂN NHƯỢNG"
    },
    {
      "id": "u48223",
      "vi": "Lão tướng kỳ cựu"
    },
    {
      "id": "u16908",
      "vi": "Bạn không thể bán cầu thủ đang gặp chấn thương."
    },
    {
      "id": "u01573",
      "vi": "Bạn không đủ ngân sách để giải phóng cầu thủ này. Vui lòng đảm bảo đủ ngân sách trước khi thực hiện."
    },
    {
      "id": "u13642",
      "vi": "Cầu thủ không khả dụng"
    },
    {
      "id": "u28755",
      "vi": "Nhấn ⟦1⟧ để tới mục Tìm kiếm Cầu thủ."
    },
    {
      "id": "u58251",
      "vi": "Cầu thủ này cam kết cống hiến toàn bộ sự nghiệp tại câu lạc bộ hiện tại và cô ấy không có ý định ra đi."
    },
    {
      "id": "u30048",
      "vi": "Câu lạc bộ này sẽ không bán cầu thủ này vì cô ấy quá quan trọng đối với đội bóng."
    },
    {
      "id": "u58386",
      "vi": "Cầu thủ này không muốn chuyển đến một giải đấu không đủ tính cạnh tranh so với khả năng của cô ấy."
    },
    {
      "id": "u35339",
      "vi": "Các điều khoản cho mượn ⟦1⟧ đã được hai câu lạc bộ thống nhất. Giờ phụ thuộc vào ⟦2⟧ và người đại diện của cô ấy để chốt thỏa thuận."
    },
    {
      "id": "u12559",
      "vi": "⟦1⟧ đã đồng ý gia nhập câu lạc bộ chúng ta theo hợp đồng cho mượn ⟦2⟧. Bạn cần hoàn tất thỏa thuận này."
    },
    {
      "id": "u19120",
      "vi": "⟦1⟧ đã đồng ý chuyển đến ⟦2⟧ theo hợp đồng cho mượn ⟦3⟧."
    },
    {
      "id": "u40629",
      "vi": "⟦1⟧ và người đại diện đang xem xét thương vụ cho mượn tới ⟦2⟧."
    },
    {
      "id": "u44963",
      "vi": "Có vẻ như cầu thủ này không muốn chuyển nơi ở vào thời điểm này."
    },
    {
      "id": "u68425",
      "vi": "Cầu thủ này đã ký hợp đồng tiền thỏa thuận với câu lạc bộ khác và sẽ không tham gia bất kỳ cuộc đàm phán chuyển nhượng nào."
    },
    {
      "id": "u25129",
      "vi": "Bạn đã thống nhất các điều khoản với ⟦1⟧. Bạn có thể bắt đầu đàm phán với cầu thủ này."
    },
    {
      "id": "u25582",
      "vi": "⟦1⟧ đã phản hồi với mức giá mới, nhưng có lẽ bạn nên thử đàm phán mức giá thấp hơn."
    },
    {
      "id": "u69974",
      "vi": "⟦1⟧ và người đại diện đã xem xét đề nghị và quyết định đồng ý. Hãy đợi ⟦2⟧ hoàn tất đàm phán với cầu thủ của bạn."
    },
    {
      "id": "u15002",
      "vi": "Chúng ta đã thống nhất các điều khoản với ⟦1⟧ và cô ấy vừa gia nhập đội bóng. Cô ấy đã sẵn sàng để tập luyện và có thể được bạn đưa vào kế hoạch cho trận đấu tới."
    },
    {
      "id": "u48820",
      "vi": "⟦1⟧ và người đại diện đã xem xét đề nghị và đồng ý. Hãy hoàn tất thương vụ để chính thức chiêu mộ cầu thủ này về đội hình của bạn."
    },
    {
      "id": "u66562",
      "vi": "⟦1⟧ nhận thấy đề nghị của ⟦2⟧ phù hợp với nhu cầu của cô ấy hơn."
    },
    {
      "id": "u27315",
      "vi": "Chúng ta đã đạt thỏa thuận tiền hợp đồng với ⟦1⟧. Cô ấy sẽ gia nhập đội ngay khi kỳ chuyển nhượng mở cửa."
    },
    {
      "id": "u36478",
      "vi": "Trợ lý HLV đang đàm phán với ⟦1⟧. Ông ấy sẽ thông báo lại cho bạn khi đạt được thỏa thuận."
    },
    {
      "id": "u61713",
      "vi": "Đàm phán với ⟦1⟧ không thành công. Bạn có thể thử lại sau một tuần nếu vẫn muốn sở hữu cầu thủ này."
    },
    {
      "id": "u60339",
      "vi": "Chúng ta chưa có đủ thông tin về cầu thủ này để đưa ra đề nghị hợp lý. Bạn nên tiếp tục tuyển trạch cô ấy."
    },
    {
      "id": "u20945",
      "vi": "⟦1⟧ đã quyết định đáp ứng mức giá bạn đưa ra. Họ sẽ bắt đầu đàm phán với cầu thủ này."
    },
    {
      "id": "u09968",
      "vi": "⟦1⟧ đang quan tâm tới việc mua cầu thủ này. Giá trị thị trường của cô ấy rơi vào khoảng ⟦2⟧ đến ⟦3⟧, vì vậy bạn có thể đàm phán một thỏa thuận tốt hơn."
    },
    {
      "id": "u36037",
      "vi": "⟦1⟧ đã đạt thỏa thuận với ⟦2⟧ và đang trên đường đến gặp các đồng đội mới."
    },
    {
      "id": "u40742",
      "vi": "⟦1⟧ và người đại diện hiện đang đàm phán với ⟦2⟧."
    },
    {
      "id": "u39402",
      "vi": "⟦1⟧ đã từ chối chuyển tới ⟦2⟧ do không đạt được thỏa thuận về các điều khoản hợp đồng."
    },
    {
      "id": "u31981",
      "vi": "⟦1⟧ muốn đề nghị ⟦2⟧ như một phần của thương vụ trao đổi. Giá trị thị trường của ⟦3⟧ rơi vào khoảng ⟦4⟧ đến ⟦5⟧, vì vậy bạn có thể đàm phán một thỏa thuận tốt hơn."
    }
  ]
