{
  "translations": [
    {
      "id": "u09515",
      "vi": "Cầu thủ trong vòng cấm"
    },
    {
      "id": "u29264",
      "vi": "Kiểm soát bóng"
    },
    {
      "id": "u23005",
      "vi": "Điều chỉnh sơ đồ tấn công của đội thành hẹp để có thêm cầu thủ ở khu trung tuyến cho các lựa chọn chuyền bóng ngắn. Hai cánh sẽ bị hở khi bạn mất quyền kiểm soát bóng."
    },
    {
      "id": "u13685",
      "vi": "Các cầu thủ sẽ hỗ trợ nhiều hơn ở khu vực tấn công thay vì thực hiện các pha chạy chỗ. Chiến thuật này tăng cường lối chơi chuyền bóng ngắn để kiên nhẫn chờ đợi cơ hội tấn công, nhưng hiếm khi tạo ra các pha chạy chỗ xuyên phá hàng phòng ngự đối phương."
    },
    {
      "id": "u08014",
      "vi": "Các cầu thủ sẽ hỗ trợ nhiều hơn trong quá trình triển khai bóng tấn công thay vì thực hiện các pha chạy chỗ. Chiến thuật này tăng cường lối chơi chuyền bóng ngắn, nhưng sẽ khiến đội của bạn mất nhiều thời gian hơn để triển khai bóng."
    },
    {
      "id": "u62664",
      "vi": "Vị trí cầu thủ"
    },
    {
      "id": "u18791",
      "vi": "Phù hợp nhất cho các đội đang cố gắng bảo vệ lợi thế dẫn trước."
    },
    {
      "id": "u38909",
      "vi": "Đội bóng sẽ phòng ngự tầm cao và kèm người sát sao để nỗ lực giành lại bóng sớm.⟦1⟧Đây là chiến thuật hiệu quả để ngăn đối phương có quá nhiều thời gian cầm bóng, nhưng dễ bị tổn thương trước các đường chuyền chọc khe sắc bén."
    },
    {
      "id": "u36356",
      "vi": "Phù hợp nhất cho các đội bóng kiên nhẫn và tự tin cầm bóng."
    },
    {
      "id": "u17112",
      "vi": "Đội bóng sẽ hướng đến việc thực hiện các đường chuyền dài từ hàng phòng ngự, vào khoảng trống sau lưng hàng thủ đối phương, hoặc lên cho một tiền đạo mục tiêu có khả năng khống chế hoặc làm tường cho đối tác tấn công.⟦1⟧Chiến thuật này phát huy tốt nhất với các đội sở hữu tiền đạo nhanh nhẹn hoặc những tiền đạo giỏi không chiến."
    },
    {
      "id": "u46267",
      "vi": "Kiểu cản phá"
    },
    {
      "id": "u28919",
      "vi": "TOP 5 GHI BÀN"
    },
    {
      "id": "u07416",
      "vi": "Chọn đội bóng"
    },
    {
      "id": "u01669",
      "vi": "Bây giờ, hãy chọn các đội bóng bạn muốn điều khiển trong giải đấu đã tạo."
    },
    {
      "id": "u31315",
      "vi": "Không nao núng khi đối mặt với tiền đạo trong tình huống một đối một, có thể tin tưởng để thực hiện những pha cứu thua khó."
    },
    {
      "id": "u05233",
      "vi": "Sở hữu bản năng sát thủ trước khung thành - một con quái vật khi đối mặt một đối một với thủ môn."
    },
    {
      "id": "u37276",
      "vi": "Cầu thủ làm tường cổ điển, tận dụng thể hình trong các pha tranh chấp trên không lẫn dưới đất."
    },
    {
      "id": "u06576",
      "vi": "Giành lại bóng bằng thể hình áp đảo. Luôn sẵn sàng cống hiến tất cả vì đội bóng."
    },
    {
      "id": "u31654",
      "vi": "Thể lực đáng kinh ngạc của cầu thủ này cho phép họ duy trì nỗ lực tối đa trong suốt trận đấu. Ngay cả khi những người khác đang xuống sức, Cỗ máy vẫn cứ chạy và chạy..."
    },
    {
      "id": "u08968",
      "vi": "Điều phối trận đấu từ tuyến dưới, cầu thủ này có thể mở toang hàng phòng ngự để tạo cơ hội cho các tiền đạo."
    },
    {
      "id": "u34351",
      "vi": "Có khả năng thực hiện những đường chuyền chuẩn xác và sắc bén, có thể phá vỡ cả những hàng phòng ngự được tổ chức tốt nhất."
    },
    {
      "id": "u40202",
      "vi": "Chốt chặn"
    },
    {
      "id": "u12089",
      "vi": "Ngòi nổ"
    },
    {
      "id": "u38784",
      "vi": "NGÒI NỔ"
    },
    {
      "id": "u26694",
      "vi": "Phù thủy"
    },
    {
