      "vi": "ĐƯỜNG CHUYỀN THÀNH CÔNG"
    },
    {
      "id": "u22120",
      "vi": "Vậy là đã có 10 pha kiến tạo trong mùa giải này! Làm tốt lắm."
    },
    {
      "id": "u22624",
      "vi": "Có vẻ như em không thể ngừng kiến tạo cho đồng đội rồi! Đã có 15 pha kiến tạo từ đầu mùa đến giờ!"
    },
    {
      "id": "u26057",
      "vi": "Việc em đã có 20 pha kiến tạo từ đầu mùa là minh chứng cho nhãn quan chiến thuật tuyệt vời của em."
    },
    {
      "id": "u28051",
      "vi": "Vậy là 25 pha kiến tạo trong mùa giải này! Tôi thực sự ấn tượng đấy."
    },
    {
      "id": "u36138",
      "vi": "40 pha kiến tạo! Hiếm có cầu thủ nào trong lịch sử bóng đá có thể tạo ra nhiều bàn thắng như vậy trong một mùa giải."
    },
    {
      "id": "u35623",
      "vi": "Em thực sự không thể ngăn cản! Việc đạt 45 pha kiến tạo trong một mùa giải đã chứng minh em đã trở thành một cầu thủ đáng kinh ngạc đến thế nào."
    },
    {
      "id": "u25713",
      "vi": "Nhãn quan chiến thuật tốt khi chuyền bóng cho đồng đội băng lên kiến tạo."
    },
    {
      "id": "u18760",
      "vi": "Pha kiến tạo hay, tầm nhìn tuyệt vời khi chọn đúng đồng đội."
    },
    {
      "id": "u33167",
      "vi": "Hãy chú ý độ chính xác. Một vài đường chuyền của em mùa này hơi thiếu chuẩn xác."
    },
    {
      "id": "u27525",
      "vi": "Hãy nhớ, chuyền cho đồng đội chứ không phải cho đối thủ. Đôi khi tôi tự hỏi không biết em có còn nhớ mình đang đá cho đội nào không nữa."
    },
    {
      "id": "u35072",
      "vi": "Số đường chuyền cho đối thủ trong mùa giải này khiến tôi tự hỏi liệu em có biết mình đang chơi cho đội nào không."
    },
    {
      "id": "u38017",
      "vi": "Em đã chuyền hỏng hơi nhiều trong mùa giải này. Cố gắng chuẩn xác hơn đi."
    },
    {
      "id": "u29968",
      "vi": "Cố gắng chuyền bóng tìm đồng đội nhiều hơn. Em đã để mất bóng quá nhiều lần trong mùa giải này."
    },
    {
      "id": "u06944",
      "vi": "Em đã để mất quyền kiểm soát bóng quá thường xuyên vì những đường chuyền cẩu thả trong mùa giải này. Chỉnh đốn lại ngay!"
    },
    {
      "id": "u45955",
      "vi": "Vị trí phòng ngự tốt, làm tốt lắm trong việc chặn các cú sút của đối phương."
    },
    {
      "id": "u00179",
      "vi": "Những pha chặn bóng đẳng cấp. Đối thủ không thể vượt qua được em."
    },
    {
      "id": "u05357",
      "vi": "Số cú sút em chặn được trong mùa giải này thật không thể tin nổi. Xuất sắc!"
    },
    {
      "id": "u13418",
      "vi": "Em đã làm tốt việc chặn các cú sút từ đầu mùa đến giờ. Hãy tiếp tục phát huy."
    },
    {
      "id": "u19403",
      "vi": "Khả năng phòng ngự tốt. Em đã chặn được một số lượng cú sút đáng kể trong mùa giải này."
    }
  ]
}

{
  "translations": [
    {
      "id": "u13669",
      "vi": "Em sút xa thiếu chính xác quá nhiều. Đừng cố thực hiện những pha bóng hoa mỹ trừ khi em tự tin có thể đưa bóng trúng đích."
    },
    {
      "id": "u34632",
      "vi": "Em đã chọn được vị trí tốt trong vòng cấm đối phương và dứt điểm rất chính xác."
    },
    {
      "id": "u08090",
      "vi": "Rất tốt khi thấy em dứt điểm trúng đích từ trong vòng cấm."
    },
    {
      "id": "u13133",
      "vi": "Nỗ lực sút xa rất tuyệt. Hãy duy trì phong độ đó, bàn thắng sẽ sớm đến thôi."
    },
    {
      "id": "u28084",
      "vi": "Tỷ lệ dứt điểm trúng đích của em thuộc hàng tốt nhất mùa giải này."
    },
    {
      "id": "u61664",
      "vi": "Những pha dứt điểm của em mùa này chuẩn xác như được lập trình vậy. Độ chính xác tuyệt vời!"
    },
    {
      "id": "u29277",
      "vi": "Em cần cải thiện độ chính xác. Mùa này, các pha dứt điểm của em không trúng đích đủ nhiều."
    },
    {
      "id": "u23819",
      "vi": "Khả năng dứt điểm của em mùa này hơi thiếu ổn định. Hãy chú ý đến độ chính xác."
    },
    {
      "id": "u38993",
      "vi": "Quá nhiều cú sút của em đi chệch mục tiêu trong mùa giải này. Thầy mong đợi nhiều hơn thế."
    },
    {
      "id": "u12944",
      "vi": "Số lượng cú sút không quan trọng bằng độ chính xác. Em nên rút kinh nghiệm về điều đó trong mùa giải này!"
    },
    {
      "id": "u44580",
      "vi": "Chuyền bóng tốt, làm tốt lắm, giúp đội nhà kiểm soát bóng hiệu quả."
    },
    {
      "id": "u06967",
      "vi": "Những quả tạt của em hôm nay lại chuẩn xác như đặt."
    },
    {
      "id": "u55487",
      "vi": "Em nên tự hào về khả năng tạt bóng mùa này. Nó đạt đẳng cấp hàng đầu."
    },
    {
      "id": "u46483",
      "vi": "Sự ổn định trong các quả tạt của em mùa này đạt đẳng cấp thế giới."
    },
    {
      "id": "u11490",
      "vi": "Thầy rất ấn tượng với độ chính xác trong các quả tạt của em mùa này."
    },
    {
      "id": "u02385",
      "vi": "Độ chính xác trong các quả tạt của em mùa này đạt đẳng cấp hàng đầu."
    },
    {
      "id": "u25091",
      "vi": "Em đã thể hiện đẳng cấp bậc thầy trong các quả tạt mùa này."
    },
    {
      "id": "u62133",
      "vi": "Những quả tạt xuất sắc."
    },
    {
      "id": "u17339",
      "vi": "Em đã thực hiện những quả tạt rất tuyệt."
    },
    {
      "id": "u46711",
      "vi": "Khả năng tạt bóng xuất sắc, làm tốt lắm trong việc tạo cơ hội cho đội bóng."
    },
    {
      "id": "u35480",
      "vi": "Những đường chuyền lên phía trên rất xuất sắc, đóng góp lớn vào nhịp độ tấn công của đội."
    },
    {
      "id": "u01697",
      "vi": "Khả năng chuyền lên của em rất xuất sắc."
    },
    {
      "id": "u48389",
      "vi": "Tầm nhìn chiến thuật tuyệt vời khi phân phối bóng bằng những đường chuyền dài."
    },
    {
      "id": "u19693",
      "vi": "Hôm nay em đã luân chuyển bóng rất tốt bằng những đường chuyền dài."
    },
    {
      "id": "u20088",
      "vi": "Những đường chuyền ngắn sắc bén, chính xác đã giúp chúng ta duy trì quyền kiểm soát bóng."
    },
    {
      "id": "u24060",
      "vi": "Những đường chuyền ngắn của em hôm nay đạt đẳng cấp rất cao."
    },
    {
      "id": "u46406",
      "vi": "Kỹ thuật chuyền bóng tốt, làm tốt lắm với những đường chuyền ngang đó."
    },
    {
      "id": "u00842",
      "vi": "Cách em phân phối bóng sang hai biên hôm nay rất nổi bật và giúp chúng ta kiểm soát thế trận."
    },
    {
      "id": "u47652",
      "vi": "Làm tốt lắm trong việc thay đổi hướng tấn công và giữ bóng."
    },
    {
      "id": "u18829",
      "vi": "Những đường chuyền đổi hướng chuẩn xác. Làm tốt lắm."
    },
    {
      "id": "u20400",
      "vi": "Rất bình tĩnh, làm tốt lắm khi xoạc bóng ngăn chặn đối phương và hóa giải cơ hội của họ."
    },
    {
      "id": "u49432",
      "vi": "Pha xoạc bóng giải nguy cuối cùng của em là một tình huống rất tuyệt."
    },
    {
      "id": "u43282",
      "vi": "Các pha xoạc bóng của em không hiệu quả, hãy cố gắng cải thiện kỹ năng này."
    },
    {
      "id": "u07450",
      "vi": "Em cần cải thiện khả năng chọn thời điểm xoạc bóng."
    },
    {
      "id": "u44251",
      "vi": "Em cần cải thiện thời điểm xoạc bóng. Mùa này có vài lần em xử lý rất cẩu thả."
    },
    {
      "id": "u39428",
      "vi": "Hãy học cách xoạc bóng đúng thời điểm hơn, nếu không em sẽ gây ra quá nhiều rắc rối cho đội bóng."
    },
    {
      "id": "u18754",
      "vi": "Việc em không thể thắng trong các pha xoạc bóng mùa này đang khiến thầy bắt đầu lo lắng."
    },
    {
      "id": "u48972",
      "vi": "Xoạc bóng có thể không phải là thế mạnh của em, nhưng mùa này nó lại tệ một cách đáng lo ngại."
    },
    {
      "id": "u09852",
      "vi": "Thầy rất lo ngại về số lần em thất bại trong các pha xoạc bóng mùa này. Cần phải cải thiện nghiêm túc!"
    },
    {
      "id": "u05201",
      "vi": "Em đã thua quá nhiều pha xoạc bóng trong mùa giải này. Như vậy là không đạt yêu cầu!"
    }
  ]
}

