    {
      "id": "u55932",
      "vi": "Chơi đối đầu nhiều người hoặc phối hợp cùng bạn bè để thăng hạng và chinh phục Division 1."
    },
    {
      "id": "u54040",
      "vi": "Tùy chỉnh cài đặt trò chơi của bạn."
    },
    {
      "id": "u66270",
      "vi": "Nâng tầm kỹ năng của bạn và xem cách bạn so tài với bạn bè trên bảng xếp hạng."
    },
    {
      "id": "u23153",
